#include &lt;bits/stdc++.h&gt;

using namespace std;

using ll = long long;

const ll p = 1e9 + 7;

const ll N = 1e5 + 9;

ll a[6][N],prefix[6][N];



int main()

{

  ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);

  int n,m;cin &gt;&gt; n &gt;&gt; m;

  for(int i = 1;i &lt;= n;++i) cin &gt;&gt; a[1][i];



  for(int i = 2;i &lt;= 5;++i)

  {

    for(int j = 1;j &lt;= n;++j)

    {

      a[i][j] = (a[i - 1][j] * a[1][j]) % p; 

    }

  }



  for(int i = 1; i&lt;= 5;++i)

  {

    for(int j = 1;j &lt;= n;++j)

    {

      prefix[i][j] = (prefix[i][j-1] + a[i][j]) % p;

    }

  }

  while(m --)

  {

    int l,r,k;cin &gt;&gt; l &gt;&gt; r &gt;&gt; k;



    cout &lt;&lt; (prefix[k][r] - prefix[k][l-1] + p) %p &lt;&lt; &#039;\n&#039;;

  }




  return 0;

}

