#include &lt;bits/stdc++.h&gt;

using namespace std;

const int N = 1e6+9;

char s[N];

int main()

{

  ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);

  cin &gt;&gt; s+1;



  int n = strlen(s+1);

  int l = 1,r = n;

  bool ans = true;

  while(l&lt;r &amp;&amp; ans)

  {

    if(s[l] != s[r]) ans = false;

    l++,r--;

  }

  cout &lt;&lt; (ans ? &#039;Y&#039; : &#039;N&#039;) &lt;&lt;&#039;\n&#039;;

  return 0;

}
