快慢指针（滑动窗口）例题：

#include &lt;bits/stdc++.h&gt;

using namespace std;

const int N = 1e5+9;

int a[N]; 

int main()

{
  ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);
  int n,s;cin &gt;&gt; n &gt;&gt; s;

  int l =1;

  int ans = n+1;

