#include &lt;iostream&gt;
#include &lt;bits/stdc++.h&gt;
using namespace std;



int main(){

  string a,b;
  cin &gt;&gt; a &gt;&gt; b;
  vector&lt;int&gt; A,B;
  for(int i = a.size()-1;i &gt;= 0;i--)
  {
    A.push_back(a[i] - &#039;0&#039;);
  }

  for(int i = b.size()-1;i &gt;= 0;i--)
  {
    B.push_back(b[i] - &#039;0&#039;);
  }

  vector&lt;int&gt; C(10000);
  for(int i = 0;i &lt; B.size();i++)
  {
    int t = 0;
    int j = 0;
    for(;j &lt; A.size();j++)
    {
      int num = t + (A[j] * B[i]);
      int ret = num % 10;
      t = num / 10;
      C[i+j] += ret;
      C[i+j+1] += C[i+j] / 10;
      C[i+j] = C[i+j] % 10;
    }
    if(t &gt; 0) C[i+j] += t;
  }

  for(int i = A.size() + B.size();i &gt;= 0;i--)
  {
    bool flag = true;
    if(flag &amp;&amp; i &gt; 0 &amp;&amp; C[i] == 0)
    {
      continue;
    }

    if(flag &amp;&amp; C[i] != 0)
    {
      flag = false;
    }
