using namespace std;

using ll = long long;

const int N = 999;

int a[N];

int main()

{

  int t;cin &gt;&gt; t;

  for(int i = 0;i &lt; t;++i)

  {

    int m,n;cin &gt;&gt; n &gt;&gt; m;

    string s;cin &gt;&gt; s;

    s = &#039;#&#039; + s;

    ll x = 0;

    for(int i = 1;i &lt; s.size();++i)

    {

      a[i] = (s[i] &lt;= &#039;9&#039;) ? s[i] - &#039;0&#039; : s[i] - &#039;A&#039; + 10; 

      x = x * n + a[i];

    }

    string ans;

    while(x) 

    {

      int res = x % m;

      ans += (res &lt; 10) ? res + &#039;0&#039; : res + &#039;A&#039; - 10,x /= m;

    }

    reverse(ans.begin(),ans.end());

    cout &lt;&lt; ans &lt;&lt;&#039;\n&#039;;
  }

  return 0;

}

